dashboard.definition:
{
    "title": "Labor und Radiologie",
    "description": "LIS-Befunde mit TAT und KIS-Zustellung, RIS-Auftraege je Modalitaet und DICOM-Speicherungen im PACS",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "lab_test": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_lis": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:lis:result\" department=\"$dept$\"\n| fields Richtung Station _time c category count critical delivered_to_kis delivery_status flag m n pos priority tat_min test_code u value ward",
                "enableSmartSources": true
            },
            "name": "Laborbefunde"
        },
        "ds_k_results": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=30m count as Befunde"
            }
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| eval c=if(critical=\"true\" OR critical=\"1\", 1, 0) | timechart span=30m sum(c) as \"Kritische Werte\""
            }
        },
        "ds_k_tat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where priority=\"Notfall\" | timechart span=30m avg(tat_min) as \"TAT Notfall\""
            }
        },
        "ds_k_undeliv": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| eval u=if(delivered_to_kis=\"false\" OR delivered_to_kis=\"0\", 1, 0) | timechart span=10m sum(u) as \"Nicht im KIS\""
            }
        },
        "ds_k_flu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where test_code=\"INFLU\" | stats count(eval(value=\"positiv\")) as pos count as n | eval \"Influenza positiv %\"=if(n>0, round(100 * pos / n, 1), 0) | fields \"Influenza positiv %\""
            }
        },
        "ds_cat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=30m count by category"
            }
        },
        "ds_tat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where category!=\"Mikrobiologie\" | timechart span=30m avg(tat_min) by priority"
            }
        },
        "ds_delivery": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=10m count by delivery_status"
            }
        },
        "ds_crit": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh department=\"$dept$\" ((sourcetype=\"sakh:lis:result\" (flag=\"HH\" OR flag=\"LL\")) OR sourcetype=\"sakh:lis:critical\")\n| eventstats min(eval(if(sourcetype=\"sakh:lis:critical\", _time, null()))) as ack_start\n| eval rt=if(sourcetype=\"sakh:lis:result\", _time, null()), acked=if(action=\"quittiert\", minutes, null()), ack_role=if(action=\"quittiert\", role, null()), told=if(action=\"mitgeteilt\", 1, null()), esc=if(action=\"eskaliert\", 1, null())\n| stats min(rt) as rt max(acked) as ack_min first(ack_role) as ack_role max(told) as told max(esc) as escalated first(test_code) as test_code first(test_name) as test_name first(value) as value first(unit) as unit first(ref_low) as ref_low first(ref_high) as ref_high first(crit_low) as crit_low first(crit_high) as crit_high first(flag) as flag first(ward) as ward first(priority) as priority first(delivery_status) as delivery_status first(patient_id) as patient_id first(ack_start) as ack_start by order_id\n| where isnotnull(rt)\n| eval ack_state=case(isnotnull(ack_min), \"quittiert\", rt>=ack_start, \"offen\", true(), \"unbekannt\")\n| eval _time=rt | sort - _time | head 300\n| table _time test_code test_name value unit ref_low ref_high crit_low crit_high flag ward priority delivery_status patient_id ack_state ack_min ack_role escalated",
                "enableSmartSources": true
            },
            "name": "Kritische Befunde mit Quittierung"
        },
        "ds_open": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh department=\"$dept$\" earliest=-4h latest=now ((sourcetype=\"sakh:lis:result\" (flag=\"HH\" OR flag=\"LL\")) OR sourcetype=\"sakh:lis:critical\")\n| eventstats min(eval(if(sourcetype=\"sakh:lis:critical\", _time, null()))) as ack_start\n| eval rt=if(sourcetype=\"sakh:lis:result\", _time, null()), acked=if(action=\"quittiert\", minutes, null()), ack_role=if(action=\"quittiert\", role, null()), told=if(action=\"mitgeteilt\", 1, null()), esc=if(action=\"eskaliert\", 1, null())\n| stats min(rt) as rt max(acked) as ack_min first(ack_role) as ack_role max(told) as told max(esc) as escalated first(test_code) as test_code first(test_name) as test_name first(value) as value first(unit) as unit first(ref_low) as ref_low first(ref_high) as ref_high first(crit_low) as crit_low first(crit_high) as crit_high first(flag) as flag first(ward) as ward first(priority) as priority first(delivery_status) as delivery_status first(patient_id) as patient_id first(ack_start) as ack_start by order_id\n| where isnotnull(rt)\n| eval ack_state=case(isnotnull(ack_min), \"quittiert\", rt>=ack_start, \"offen\", true(), \"unbekannt\")\n| where ack_state=\"offen\" | eval age=round((now() - rt) / 60, 0)",
                "enableSmartSources": true
            },
            "name": "Offene kritische Befunde"
        },
        "ds_k_open": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_open",
                "query": "| stats count as \"Nicht quittiert\""
            }
        },
        "ds_k_overdue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_open",
                "query": "| where age>30 | stats count as \"Ueber 30 min\""
            }
        },
        "ds_open_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_open",
                "query": "| sort - age\n| eval Status=case(escalated=1, \"eskaliert an Oberarzt\", told=1, \"telefonisch mitgeteilt\", true(), \"noch nicht mitgeteilt\"), Wert=value.\" \".unit, Richtung=if(flag=\"HH\", \"zu hoch\", \"zu niedrig\")\n| table ward age test_name Wert Richtung Status delivery_status\n| rename ward as Station age as \"Seit (min)\" test_name as Test delivery_status as KIS\n| appendpipe [| stats count | where count=0 | eval Station=\"Alle kritischen Werte sind quittiert\" | fields - count]"
            }
        },
        "ds_ack": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:lis:critical\" department=\"$dept$\"\n| fields Dauer _time action count h minutes ok",
                "enableSmartSources": true
            },
            "name": "Meldung kritischer Werte"
        },
        "ds_k_ack_med": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ack",
                "query": "| where action=\"quittiert\" | timechart span=1h median(minutes) as \"Median\""
            }
        },
        "ds_k_ack_30": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ack",
                "query": "| where action=\"quittiert\" | eval ok=if(minutes<=30, 100, 0) | timechart span=1h avg(ok) as \"Innerhalb 30 min\""
            }
        },
        "ds_ack_buckets": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ack",
                "query": "| where action=\"quittiert\"\n| eval Dauer=case(minutes<=10, \"bis 10 min\", minutes<=30, \"10 bis 30 min\", true(), \"ueber 30 min (eskaliert)\")\n| timechart span=1h count by Dauer"
            }
        },
        "ds_crit_ward": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| search (flag=\"HH\" OR flag=\"LL\") test_code=\"$lab_test$\"\n| eval Richtung=if(flag=\"HH\", \"zu hoch\", \"zu niedrig\")\n| chart count over ward by Richtung | rename ward as Station\n| appendpipe [| stats count | where count=0 | eval Station=\"Keine kritischen Werte im Zeitraum\" | fields - count]"
            }
        },
        "ds_ris": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ris:order\" department=\"$dept$\"\n| fields Tage Zeit _time count device_id exam modality order_id original_device priority reason status wait_days",
                "enableSmartSources": true
            },
            "name": "RIS-Auftraege"
        },
        "ds_modality": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| chart count over modality by status"
            }
        },
        "ds_wait": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| where priority=\"Routine\" | stats avg(wait_days) as \"Wartezeit (Tage)\" by modality | eval \"Wartezeit (Tage)\"=round('Wartezeit (Tage)', 1)"
            }
        },
        "ds_moved": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| where status=\"umgeplant\"\n| eval Zeit=strftime(_time, \"%H:%M\") | table Zeit order_id exam original_device device_id reason wait_days\n| rename order_id as Auftrag exam as Untersuchung original_device as \"Geplant auf\" device_id as \"Neu auf\" reason as Grund wait_days as \"Wartezeit (Tage)\"\n| appendpipe [| stats count | where count=0 | eval Zeit=\"Keine umgeplanten Untersuchungen im Zeitraum\" | fields - count]"
            }
        },
        "ds_pacs": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pacs:dicom\" | timechart span=30m sum(size_mb) as MB by modality",
                "enableSmartSources": true
            },
            "name": "PACS Datenvolumen"
        },
        "ds_pacs_fail": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pacs:dicom\" status!=\"Success\" | stats count as Fehler by device_id status | rename device_id as Modalitaet status as Fehlerbild | appendpipe [| stats count | where count=0 | eval Modalitaet=\"Keine Speicherfehler im Zeitraum\" | fields - count]",
                "enableSmartSources": true
            }
        },
        "ds_device": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| stats count by device_id | sort - count | head 12"
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_klinik/images/nav_care.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_klinik",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
